<?php
namespace App\Modules\Settlement\Presentation\Http\Controllers;
use App\Http\Controllers\Controller;
use App\Modules\Settlement\Application\UseCases\{FinalizeSettlement,GetSettlement,GetSettlementItems,GetSettlementSettings,ImportSettlement,UpdateSettlementSetting};
use App\Modules\Settlement\Presentation\Http\Requests\{FinalizeSettlementRequest,SettlementReadRequest,SettlementRequest,SettlementSettingsRequest};
use Illuminate\Http\JsonResponse;
final class SettlementController extends Controller { public function import(SettlementRequest $r,ImportSettlement $u):JsonResponse{$d=$r->validated();return response()->json(['data'=>$u->execute($r->file('file')->getRealPath(),$d['provider_code'],$d['period_from']??null,$d['period_to']??null)],201);} public function show(SettlementReadRequest $r,int $id,GetSettlement $u):JsonResponse{return response()->json(['data'=>$u->execute($id)]);} public function items(SettlementReadRequest $r,int $id,GetSettlementItems $u):JsonResponse{return response()->json(['data'=>$u->execute($id)]);} public function finalize(FinalizeSettlementRequest $r,int $id,FinalizeSettlement $u):JsonResponse{return response()->json(['data'=>$u->execute($id)]);} public function settings(SettlementSettingsRequest $r,GetSettlementSettings $u):JsonResponse{return response()->json(['data'=>$u->execute()]);} public function updateSetting(SettlementSettingsRequest $r,UpdateSettlementSetting $u):JsonResponse{$d=$r->validated();return response()->json(['data'=>$u->execute($d['key'],$d['value'])]);} }
